import {
  Configuration, ExtractionApi, OutputFormat,
} from "@geonode_scraper/scraper-sdk";

const apiKey = process.env.GEONODE_SCRAPER_API_KEY;
if (!apiKey) throw new Error("Set GEONODE_SCRAPER_API_KEY");

const configuration = new Configuration({ apiKey });
const response = await new ExtractionApi(configuration).extractV1ExtractPost({
  extractRequest: {
    url: "https://example.com",
    formats: [OutputFormat.Markdown],
  },
});

if ("data" in response) {
  console.log(response.data.markdown);
  console.log(response.tokensCharged);
}
